/*
  герой.js — ЛОГИКА. Порядок экранов, правила проверки, хранение,
  генерация портрета, сборка карточки для отправки.

  Чем отличается от соседей: здесь нет ни одного текста, который видит
  человек, и ни одного настроечного числа. Тексты берутся из мир.js,
  числа и адреса — из настройки.js, список брани — из брань.js.
  Это условие приёмки, а не пожелание: правка содержания не должна
  требовать правки логики.

  Порядок работы: разобрали тему → достали сохранённого героя →
  показали нужный экран.
*/

/*  Всё содержимое файла лежит в своей области. Причина: сборка героя
    и мир теперь живут на ОДНОМ адресе, а имена НАСТРОЙКИ, МИР и $ у
    них были одинаковые — вместе они бы стёрли друг друга.         */
window.СБОРКА = (function () {

'use strict';

const НАСТРОЙКИ = window.СБОРКА_НАСТРОЙКИ;
const МИР       = window.СБОРКА_ДАННЫЕ;
const { БРАНЬ } = window.СБОРКА_БРАНЬ;

const $ = (ид) => document.getElementById(ид);

/* ── состояние ─────────────────────────────────────────────────────
   «выбор» живёт только во время сборки, «герой» — то, что сохранено. */
let выбор = null;
let герой = null;
let шаг = 0;
let поломка = false;      // запись есть, но прочитать её не вышло

/* ═══ 1 · ГАММА ════════════════════════════════════════════════════
   Цвета брались у Телеграма, и ради этого страница тянула его скрипт
   с чужого сервера. Убрано: главный вход теперь браузер, а правило
   «ни одной ссылки на чужой сервер» — общее для всего проекта.
   Гамма целиком лежит в стиль.821f58db.css, одним набором на весь адрес.  */

function применитьОттенок(ключНарода) {
  document.documentElement.style.setProperty(
    '--оттенок', МИР.народы[ключНарода].оттенок);
}

/* ═══ 2 · ТЕКСТЫ ═══════════════════════════════════════════════════ */

/*  Разметка теперь одна на весь адрес, и метки в ней есть у обеих
    частей. Расставляем только свои: чужого ключа в нашем словаре
    нет, и то место остаётся как было — его заполнит мир.          */
function расставитьТексты() {
  document.querySelectorAll('[data-т]').forEach((узел) => {
    const слово = МИР.тексты[узел.dataset.т];
    if (слово !== undefined) узел.textContent = слово;
  });
}

/* ═══ 3 · МЕЛОЧИ ═══════════════════════════════════════════════════ */

const случайное = (сколько) => Math.floor(Math.random() * сколько);
const ключиНародов = () => Object.keys(МИР.народы);

function знакНарода(ключ, размер) {
  const н = МИР.народы[ключ];
  return '<svg xmlns="' + НАСТРОЙКИ.знак.пространствоИмён +
    '" width="' + размер + '" height="' + размер +
    '" viewBox="' + НАСТРОЙКИ.знак.холст + '" fill="none" stroke="' + н.оттенок +
    '" stroke-width="' + НАСТРОЙКИ.знак.толщинаЛинии +
    '" stroke-linejoin="round">' + н.знак + '</svg>';
}

/* Размеры знака заданы в css через переменные бокса, а сам svg рисуется
   от размера своего места — берём его из вычисленного стиля. */
function вставитьЗнак(узел, ключ) {
  const сторона = Math.round(узел.clientWidth * НАСТРОЙКИ.знак.доля)
    || НАСТРОЙКИ.знак.поУмолчанию;
  узел.innerHTML = знакНарода(ключ, сторона);
}

/* ═══ 4 · ЭКРАНЫ ═══════════════════════════════════════════════════ */

const ЭКРАНЫ = ['э-вступление', 'э-конструктор', 'э-герой'];

function показатьЭкран(ид) {
  ЭКРАНЫ.forEach((э) => { $(э).hidden = (э !== ид); });
  window.scrollTo(0, 0);
}

function показатьШаг(номер) {
  шаг = номер;
  for (let i = 1; i <= НАСТРОЙКИ.шагов; i++) $('шаг-' + i).hidden = (i !== номер);
  Array.from($('полоска').children).forEach((и, i) => {
    и.classList.toggle('есть', i < номер);
  });
  window.scrollTo(0, 0);
}

/* ═══ 5 · КОНСТРУКТОР ══════════════════════════════════════════════
   Ощущение конструктора держится на трёх вещах: значения стоят с
   первой секунды, предпросмотр меняется на каждый выбор, есть
   «перемешать». Пустых полей не бывает.                            */

function случайныйВыбор() {
  const народ = ключиНародов()[случайное(ключиНародов().length)];
  const н = МИР.народы[народ];
  return {
    народ: народ,
    пол: МИР.полы[случайное(МИР.полы.length)].ключ,
    телосложение: МИР.телосложения[случайное(МИР.телосложения.length)].ключ,
    цвет: н.цвета[случайное(н.цвета.length)].имя,
    отметина: МИР.отметины[случайное(МИР.отметины.length)].ключ,
    имя: '',
    девиз: н.девизы[случайное(н.девизы.length)].ключ,
    /*  ПЛАЩ ЧЕЛОВЕК БОЛЬШЕ НЕ ВЫБИРАЕТ. Одежду задаёт народ, и шести
        цветов плаща на фигурах нет вовсе — выбор обещал бы то, чего
        человек не увидит. Само поле осталось: им красится фигурка,
        нарисованная кодом, пока библиотеки лиц нет.

        Вернётся накидкой, дорисованной кодом поверх фигуры. В
        библиотеку плащ не вводится: шесть цветов умножили бы её до
        2304 картинок.                                              */
    плащ: МИР.плащи[случайное(МИР.плащи.length)].имя,
    зерно: случайное(НАСТРОЙКИ.зерно.предел)
  };
}

function случайноеИмя(ключНарода) {
  const слоги = МИР.народы[ключНарода].слоги;
  return слоги[случайное(слоги.length)] +
         слоги[случайное(слоги.length)].toLowerCase();
}

function нарисоватьНароды() {
  $('народы').innerHTML = ключиНародов().map((к) => {
    const н = МИР.народы[к];
    // рамка знака красится в цвет своего народа, а не выбранного:
    // иначе все четыре знака выглядят одинаково и выбор не читается
    return '<div class="народ' + (к === выбор.народ ? ' выбран' : '') +
      '" data-народ="' + к + '" style="border-color:' +
      (к === выбор.народ ? н.оттенок : 'transparent') + '">' +
      '<div class="знак" style="border-color:' + н.оттенок + '">' +
      знакНарода(к, НАСТРОЙКИ.знак.поУмолчанию) + '</div>' +
      '<div><b>' + н.имя + '</b><span>' + н.о + '</span></div></div>';
  }).join('');
}

function нарисоватьОблик() {
  const н = МИР.народы[выбор.народ];

  $('полы').innerHTML = МИР.полы.map((п) =>
    '<div class="вар' + (п.ключ === выбор.пол ? ' выбран' : '') +
    '" data-пол="' + п.ключ + '">' + п.имя + '</div>').join('');

  $('телосложения').innerHTML = МИР.телосложения.map((т) =>
    '<div class="вар' + (т.ключ === выбор.телосложение ? ' выбран' : '') +
    '" data-телосложение="' + т.ключ + '">' + т.имя + '</div>').join('');

  $('цвета').innerHTML = н.цвета.map((ц) =>
    '<div class="цвет' + (ц.имя === выбор.цвет ? ' выбран' : '') +
    '" style="background:' + ц.код + '" title="' + ц.имя +
    '" data-цвет="' + ц.имя + '"></div>').join('');

  $('отметины').innerHTML = МИР.отметины.map((о) =>
    '<div class="вар' + (о.ключ === выбор.отметина ? ' выбран' : '') +
    '" data-отметина="' + о.ключ + '">' + о.имя + '</div>').join('');

}

function обновитьПревью() {
  const н = МИР.народы[выбор.народ];
  const т = МИР.телосложения.find((э) => э.ключ === выбор.телосложение);
  const о = МИР.отметины.find((э) => э.ключ === выбор.отметина);
  const подпись = подставить(МИР.шаблоны.облик, {
    народ: н.имя.toLowerCase(), телосложение: т.имя,
    цвет: выбор.цвет, отметина: о.имя
  });

  применитьОттенок(выбор.народ);
  ['знак-превью', 'знак-сводка'].forEach((ид) => вставитьЗнак($(ид), выбор.народ));
  $('имя-превью').textContent = выбор.имя || МИР.тексты.безымянный;
  $('имя-сводка').textContent = выбор.имя || МИР.тексты.безымянный;
  $('облик-превью').textContent = подпись;
  $('облик-сводка').textContent = подпись;
}

function перерисоватьВсё() {
  нарисоватьНароды();
  нарисоватьОблик();
  обновитьПревью();
}

function выбратьНарод(ключ) {
  if (ключ === выбор.народ) return;
  выбор.народ = ключ;
  // список цветов свой у каждого народа, поэтому выбор цвета сбрасываем
  выбор.цвет = МИР.народы[ключ].цвета[0].имя;
  const девизы = МИР.народы[ключ].девизы;
  выбор.девиз = девизы[случайное(девизы.length)].ключ;
  перерисоватьВсё();
}

function перемешать() {
  const было = выбор.имя;
  выбор = случайныйВыбор();
  выбор.имя = было || случайноеИмя(выбор.народ);
  $('поле-имя').value = выбор.имя;
  перерисоватьВсё();
  проверитьИмя();
}

/* ═══ 6 · ИМЯ ══════════════════════════════════════════════════════ */

function ошибкаИмени(значение) {
  const п = НАСТРОЙКИ.имя;
  const т = МИР.тексты;
  if (!значение.length) return '';
  if (значение.length < п.мин) return т.ошибка_коротко;
  if (значение.length > п.макс) return т.ошибка_длинно;
  if (new RegExp(п.цифры).test(значение)) return т.ошибка_цифры;
  if (new RegExp(п.разрешённыеЗнаки).test(значение)) return т.ошибка_знаки;
  if (new RegExp(п.дваПробела).test(значение)) return т.ошибка_пробелы;
  const строчными = значение.toLowerCase();
  if (БРАНЬ.some((слово) => строчными.includes(слово))) return т.ошибка_брань;
  return '';
}

function проверитьИмя() {
  const значение = $('поле-имя').value.trim();
  выбор.имя = значение;
  const ошибка = ошибкаИмени(значение);
  $('ошибка-имени').textContent = ошибка;
  $('к-имя-дальше').disabled = !(значение.length >= НАСТРОЙКИ.имя.мин && !ошибка);
  обновитьПревью();
}

/* ═══ 7 · СБОРКА ФРАЗ ══════════════════════════════════════════════
   Строка судьбы и описание портрета собираются по шаблонам из мир.js.
   Ни одна фраза не написана здесь, и ни одна не приходит от человека. */

function подставить(шаблон, значения) {
  // имена подстановок русские, поэтому \w тут не годится: он покрывает
  // только латиницу и цифры, и шаблон оставался бы неразобранным
  return шаблон.replace(/\{([^{}]+)\}/g, (всё, ключ) =>
    (ключ in значения) ? значения[ключ] : всё);
}

function строкаСудьбы(з) {
  const н = МИР.народы[з.народ];
  return подставить(МИР.судьба, {
    народ: н.имя,
    земля: н.земля,
    телосложение: МИР.телосложения.find((э) => э.ключ === з.телосложение).вФразе,
    отметина: МИР.отметины.find((э) => э.ключ === з.отметина).вФразе
  });
}

function описаниеПортрета(з) {
  const н = МИР.народы[з.народ];
  const части = {
    пол: МИР.полы.find((э) => э.ключ === з.пол).англ,
    одежда: н.одеждаАнгл,
    народ: н.англ,
    волосы: н.волосыАнгл,
    цвет: н.цвета.find((э) => э.имя === з.цвет).англ,
    телосложение: МИР.телосложения.find((э) => э.ключ === з.телосложение).англ,
    отметина: МИР.отметины.find((э) => э.ключ === з.отметина).англ
  };
  /*  ПОРЯДОК ЖЁСТКИЙ: приметы героя, свободный текст, каркас стиля.

      Каркас идёт ПОСЛЕДНИМ. Когда он стоял первым, шесть героев
      разных народов вышли одним лицом: модель слушает начало запроса
      и до примет не дочитывает.

      Запретного здесь нет вовсе. Раньше «no nudity, no violence»
      дописывалось в текст — а модель читает не «no», а сами слова, и
      строка, которой мы запрещали наготу, наготу и подсказывала.
      Теперь запретное уходит отдельным полем, см. `запретДля`.

      Свободного текста здесь тоже нет и не будет: описание складывает
      программа из выбранного. За то, что человек напишет сам,
      отвечать пришлось бы владельцу площадки.                       */
  const куски = [
    подставить(МИР.описаниеПортрета, части),
    НАСТРОЙКИ.портрет.каркас
  ];
  // пустая отметина не должна оставлять две запятые подряд
  return куски.filter(Boolean).join(', ')
    .replace(/,\s*,/g, ',').replace(/\s+/g, ' ').trim();
}

/*  ЧТО ЭТОМУ ГЕРОЮ РИСОВАТЬ НЕЛЬЗЯ.

    Общий хвост плюс запрет его народа. Одним списком на всех обойтись
    нельзя: Гарнаху острые уши запрещены, а Аэльву они положены —
    общий запрет отобрал бы их у эльфа.

    Уходит ОТДЕЛЬНЫМ полем, а не текстом запроса: модель читает не
    «no pointed ears», а «pointed ears».                             */
function запретДля(з) {
  const н = МИР.народы[з.народ];
  return [НАСТРОЙКИ.портрет.хвост, н && н.нельзя].filter(Boolean).join(', ');
}

/* ═══ 8 · ПОРТРЕТ ══════════════════════════════════════════════════
   Сохраняем сам файл, а не ссылку: сервис однажды поменяет модель, и
   лицо героя изменится. Это ломает главное обещание — герой не
   меняется никогда.                                                 */

/* Метка этого браузера. Не опознание человека: случайное число, по
   которому посредник считает портреты по устройствам. Сотрут память
   браузера — метка пропадёт, так и задумано. */
function меткаУстройства() {
  const х = НАСТРОЙКИ.хранение;
  try {
    let метка = localStorage.getItem(х.ключУстройства);
    if (!метка) {
      метка = crypto.randomUUID();
      localStorage.setItem(х.ключУстройства, метка);
    }
    return метка;
  } catch (е) {
    // память закрыта — метка живёт до перезагрузки, счёт держит адрес сети
    return меткаУстройства.разовая ||
      (меткаУстройства.разовая = crypto.randomUUID());
  }
}

/* Картинку храним ФАЙЛОМ, а не ссылкой: генератор когда-нибудь сменит
   модель, и лицо героя изменилось бы. Герой не меняется никогда. */
function изБайт(кусок) {
  return new Promise((готово, беда) => {
    const адрес = URL.createObjectURL(кусок);
    const кадр = new Image();
    кадр.onload  = () => { URL.revokeObjectURL(адрес); готово(кадр); };
    кадр.onerror = () => { URL.revokeObjectURL(адрес); беда(new Error()); };
    кадр.src = адрес;
  });
}

/*  Пришедшая картинка, перерисованная на холсте под размер записи.

    Перерисовка здесь не ради размера. В JPEG от генератора лежит Exif
    с нашим запросом открытым текстом, а картинка расходится по людям.
    Холст переносит только точки — Exif пересъёмку не переживает.

    Кадр заказа и холст записи одного отношения сторон (512×768 против
    256×384), поэтому это простое уменьшение без обрезки. Если
    отношение когда-нибудь разойдётся, лишнее срежется по краям, а не
    сплющится: сплющенный герой хуже обрезанного.                    */
function вписать(кадр, окно) {
  const вид = НАСТРОЙКИ.портрет.картинка.вид;
  const доля = Math.max(окно.ширина / кадр.naturalWidth,
                        окно.высота / кадр.naturalHeight);
  const ш = кадр.naturalWidth * доля, в = кадр.naturalHeight * доля;

  const холст = document.createElement('canvas');
  холст.width = окно.ширина;
  холст.height = окно.высота;
  холст.getContext('2d').drawImage(кадр, (окно.ширина - ш) / 2, (окно.высота - в) / 2, ш, в);
  return холст.toDataURL(вид, окно.качество);
}

/*  Байты от генератора → картинка записи.

    ОДНА КАРТИНКА НА ГЕРОЯ — его собственная фигура во весь рост.
    Портрет по грудь и медальон отменены вместе с рисованной фигуркой:
    по карте ходит сам герой.                                        */
async function разобрать(кусок) {
  const кадр = await изБайт(кусок);
  return { фигура: вписать(кадр, НАСТРОЙКИ.портрет.картинка.фигура) };
}

/*  ДВА ИСТОЧНИКА КАРТИНОК, выбор между ними — одна строка в
    настройках. Имена веток здесь не пишутся строками: строка с
    русскими буквами в логике — это текст, а тексты живут в мир.js.
    Ключ из настроек попадает сюда прямо.                           */
const ИСТОЧНИКИ = {
  посредник: {
    ходок: (з, сторож) => уПосредника(з, сторож),
    готов: () => Boolean(НАСТРОЙКИ.портрет.адрес)
  },
  pollinations: {
    ходок: (з, сторож) => уВремянки(з, сторож),
    готов: () => Boolean(НАСТРОЙКИ.портрет.времянка.адрес)
  }
};

/*  Есть ли вообще чем рисовать. У времянки адрес свой и всегда есть,
    у посредника он вписывается после выкладки.                     */
function генерацияЕсть() {
  const и = ИСТОЧНИКИ[НАСТРОЙКИ.портрет.источник];
  return Boolean(и) && и.готов();
}

/* Просим портрет у посредника. Возвращаем либо картинку, либо код
   беды. Пустой адрес — посредника ещё нет, и это не поломка: герой
   создаётся без портрета и входит в мир. */
/*  Наш посредник. Ключ, счёт по людям и выбор модели — всё там.  */
function уПосредника(з, сторож) {
  const п = НАСТРОЙКИ.портрет;
  return fetch(п.адрес + '?' + new URLSearchParams({ дело: п.дело }), {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      описание: описаниеПортрета(з),
      запрет: запретДля(з),     // отдельным полем, а не в тексте запроса
      ширина: п.ширина,
      высота: п.высота,
      зерно: з.зерно,
      устройство: меткаУстройства()
    }),
    signal: сторож
  });
}

/*  Времянка. Ходит к генератору прямо из браузера: ключа у неё нет и
    прятать нечего, счёт держит сам поставщик.

    Запретное уходит полем `negative_prompt`, а НЕ текстом запроса:
    модель читает не «no nudity», а «nudity», и строка, которой мы
    запрещали наготу, наготу и подсказывала.

    Метка устройства сюда не идёт: считать по людям нечем, а лишних
    сведений наружу не отдаём.                                      */
function уВремянки(з, сторож) {
  const п = НАСТРОЙКИ.портрет;
  return fetch(п.времянка.адрес + encodeURIComponent(описаниеПортрета(з)) + '?' +
    new URLSearchParams({
      width: п.ширина, height: п.высота, seed: з.зерно,
      nologo: 'true', private: 'true', negative_prompt: запретДля(з)
    }), { signal: сторож });
}

/*  Просим портрет. Возвращаем либо две готовые картинки, либо код
    беды. Нет источника — это не поломка: герой создаётся без портрета
    и входит в мир.                                                 */
async function получитьПортрет(з) {
  const п = НАСТРОЙКИ.портрет;
  if (!генерацияЕсть()) return { беда: п.коды.нетПосредника };

  const сторож = new AbortController();
  const будильник = setTimeout(() => сторож.abort(), п.ожиданиеМс);
  try {
    const ответ = await ИСТОЧНИКИ[п.источник].ходок(з, сторож.signal);
    if (!ответ.ok) {
      const сказано = await ответ.json().catch(() => null);
      return { беда: (сказано && сказано.беда) || п.коды.отказ };
    }
    const своя = await разобрать(await ответ.blob());
    return { ...своя, источник: п.источник };
  } catch (е) {
    return { беда: п.коды.отказ };
  } finally {
    clearTimeout(будильник);
  }
}

/*  ИМЯ ФАЙЛА В БИБЛИОТЕКЕ. Собрано из ключей выбора: ключи уже лежат
    в записи, и картинка находится по имени, без списка соответствий.

    Цвет кожи хранится ИМЕНЕМ, и в нём бывает пробел («лунная кость»).
    В имени файла пробел заменяется дефисом — иначе адрес пришлось бы
    кодировать при каждом обращении.                                */
function ключФигуры(з) {
  return НАСТРОЙКИ.портрет.библиотека.ключи
    .map((к) => String(з[к]).replace(/\s+/g, '-')).join('_');
}

const фигураИзБиблиотеки = (з) =>
  НАСТРОЙКИ.портрет.библиотека.фигуры + ключФигуры(з) + НАСТРОЙКИ.портрет.библиотека.вид;

/*  Что показать в карточке. СВОЁ ЛИЦО ЗАМЕЩАЕТ БИБЛИОТЕЧНОЕ НАВСЕГДА:
    если оно есть, в библиотеку не смотрим вовсе.

    Нет ни того, ни другого — рисуем знак народа, как было до
    библиотеки. Мир открывается всегда, это условие приёмки.        */
function показатьПортрет(з) {
  const место = $('портрет');
  место.innerHTML = '';

  const кадр = new Image();
  кадр.alt = '';
  кадр.onerror = () => {
    место.innerHTML = '<div class="знак">' +
      знакНарода(з.народ, Math.round(место.clientHeight * НАСТРОЙКИ.знак.доля)) + '</div>';
  };
  кадр.src = з.портрет || фигураИзБиблиотеки(з);
  место.appendChild(кадр);

  // кнопка «нарисовать моё лицо» гаснет, только когда попытки кончились
  $('к-портрет').hidden = попыткиКончились(з);
}

function попыткиКончились(з) {
  return (з.попыток || 0) >= НАСТРОЙКИ.портрет.попытокПредел;
}

async function догнатьПортрет() {
  if (попыткиКончились(герой)) return;
  $('к-портрет').disabled = true;
  $('портрет').innerHTML = '<div class="ждём">' + МИР.тексты.портрет_ждём + '</div>';

  /*  Новое зерно на каждую попытку. Иначе «попробовать ещё раз»
      возвращало бы ту же самую картинку: посредник помнит сделанное
      и на тот же запрос честно отдаёт прежний ответ.               */
  герой.зерно = случайное(НАСТРОЙКИ.зерно.предел);

  /*  Кнопку возвращаем В ЛЮБОМ СЛУЧАЕ.

      Однажды она погасла навсегда: строка от отменённого замысла
      ссылалась на переменную, которой уже не было, и при строгом
      режиме бросала ошибку сразу после гашения. Человек нажимал, и
      не происходило ничего — ни картинки, ни отказа, ни объяснения.
      Теперь любая поломка оставляет кнопку живой.                 */
  try {
    const вышло = await получитьПортрет(герой);
    if (положитьПортрет(герой, вышло)) герой.попыток = (герой.попыток || 0) + 1;
    сообщитьОПортрете(герой, вышло.беда);
    сохранить(герой);
  } finally {
    показатьПортрет(герой);
    $('к-портрет').disabled = false;
  }
}

/*  Молчаливая пересборка портрета, сделанного до посредника.

    Старые портреты рисовала Sana, её лицензия запрещает коммерцию.
    Пока живых людей нет — это ничего не стоит; когда придут, менять
    будет уже нельзя незаметно. Поэтому меняем сейчас и молча: ни
    сообщения, ни ожидания — вышло, так вышло.                      */
async function обновитьСтарыйПортрет() {
  if (!герой || !герой.портретСтарый || !генерацияЕсть()) return;
  const вышло = await получитьПортрет(герой);
  if (!положитьПортрет(герой, вышло)) return;  // не вышло — старый пока остаётся
  сохранить(герой);
  показатьПортрет(герой);
}

/* Что написать под героем после попытки получить портрет. */
/*  Посредник называет беду КОДОМ, а не словами: все человеческие
    тексты живут в `мир.js`, и на сервере им делать нечего. Здесь код
    превращается в надпись. Незнакомый код — общая надпись.         */
function сообщитьОПортрете(з, беда) {
  const т = МИР.тексты;
  if (з.портрет && !беда) {
    $('сообщение').textContent = попыткиКончились(з) ? т.портрет_попытки : '';
    return;
  }
  $('сообщение').textContent =
    т[НАСТРОЙКИ.портрет.коды.приставка + беда] || т.портрет_нет;
}

/* ═══ 9 · ХРАНЕНИЕ ═════════════════════════════════════════════════ */

/*  Цвета фигурки. Кожа выбирается человеком в шаге облика, волосы
    задаёт народ, плащ выбирается отдельно. Если чего-то нет — берём
    первое из списка, чтобы фигурка нарисовалась в любом случае.   */

function цветКожи(з) {
  const цвета = МИР.народы[з.народ].цвета;
  return (цвета.find((ц) => ц.имя === з.цвет) || цвета[0]).код;
}

function цветПлаща(з) {
  return (МИР.плащи.find((п) => п.имя === з.плащ) || МИР.плащи[0]).код;
}

function сохранить(запись) {
  try {
    localStorage.setItem(НАСТРОЙКИ.хранение.ключ, JSON.stringify(запись));
    return true;
  } catch (е) {
    return false;             // память браузера переполнена — герой уже на экране
  }
}

/*  ЧТЕНИЕ ЗАПИСИ. Три исхода, и путать их нельзя.

    ПУСТО   — записи нет: человек здесь впервые, ему ворота.
    ЗАПИСЬ  — прочитана, герой на месте.
    ПОЛОМКА — запись ЕСТЬ, но прочитать её не вышло.

    Третий случай раньше выдавался за первый: всё, что падало внутри,
    ловил один `catch`, и наружу уходило «героя нет». Человек вместо
    своего мира получал ворота, будто он тут впервые. Так и случилось
    однажды: ошибка в пути к библиотеке роняла чтение, и герой
    выглядел пропавшим.

    Герой у нас «навсегда». Потерять его из-за НАШЕЙ ошибки нельзя,
    поэтому при поломке запись не трогаем вовсе: ни стирания, ни
    перезаписи. Стереть её может только человек и только прямой
    кнопкой, с вопросом.                                            */
function достать() {
  let строка;
  try {
    строка = localStorage.getItem(НАСТРОЙКИ.хранение.ключ);
  } catch (е) {
    // память браузера закрыта совсем: записи нет и взяться ей неоткуда
    return { пусто: true };
  }
  if (!строка) return { пусто: true };

  try {
    const запись = JSON.parse(строка);
    // народ мог исчезнуть из мир.js — переводить такую запись нечем
    if (!запись || !МИР.народы[запись.народ]) return { поломка: true };

    const переведена = перевести(запись);
    if (!записьЦела(переведена)) return { поломка: true };

    /*  Сохраняем ТОЛЬКО после проверки: перевод дописывает поля, и
        негодную запись переписывать своей рукой незачем.          */
    снабдитьЛицом(переведена);
    сохранить(переведена);
    return { запись: переведена };
  } catch (е) {
    return { поломка: true };
  }
}

/*  ЗАПИСЬ ПРОВЕРЯЕТСЯ ПРИ ЧТЕНИИ, А НЕ ТОЛЬКО ПРИ ВВОДЕ.

    Ввода могло не быть вовсе: запись лежит в памяти браузера, которую
    человек правит руками, и приходит от друга кодом переноса героя.
    Проверка при вводе стережёт только честный путь.

    Имя проверяется теми же правилами, что и при вводе, включая длину.
    Ключи выбора должны найтись в мир.js — по ним же собирается имя
    файла в библиотеке. Цвета обязаны быть цветами, картинки —
    картинками.

    Не сошлось — запись негодна, и человек видит разговор о поломке.
    Стирать её мы всё равно не имеем права: герой «навсегда».      */
function записьЦела(з) {
  if (!з || typeof з !== 'object') return false;

  if (typeof з.имя !== 'string') return false;
  з.имя = з.имя.trim();
  if (з.имя.length < НАСТРОЙКИ.имя.мин) return false;
  if (з.имя.length > НАСТРОЙКИ.имя.макс) return false;
  if (ошибкаИмени(з.имя)) return false;

  const н = МИР.народы[з.народ];
  if (!н) return false;
  if (!МИР.полы.some((п) => п.ключ === з.пол)) return false;
  if (!МИР.телосложения.some((т) => т.ключ === з.телосложение)) return false;
  if (!МИР.отметины.some((о) => о.ключ === з.отметина)) return false;
  if (!н.цвета.some((ц) => ц.имя === з.цвет)) return false;
  if (!МИР.плащи.some((п) => п.имя === з.плащ)) return false;
  if (!н.девизы.some((д) => д.ключ === з.девиз)) return false;

  const п = НАСТРОЙКИ.запись;
  for (const поле of п.цветныеПоля) {
    if (!п.цвет.test(String(з[поле]))) return false;
  }
  for (const поле of п.картинки) {
    if (з[поле] && !п.картинка.test(String(з[поле]))) return false;
  }
  if (!Number.isFinite(з.зерно)) return false;
  return true;
}

/*  Экран поломки. Кнопка «создать героя» прячется: новый затёр бы
    прежнего, а прежнего мы ещё надеемся прочитать.                 */
function показатьПоломку() {
  $('поломка').hidden = false;
  $('к-начать').hidden = true;
}

/*  Перевод записи на нынешнее устройство.

    Портреты старее второй версии рисовала Sana — её лицензия
    запрещает коммерцию. Такой портрет помечается и при первом же
    входе молча заменяется новым, сделанным через посредника.
    Счётчик попыток при этом обнуляется: человек ни в чём не виноват
    и не должен из-за нашего переезда остаться без портрета.        */
function перевести(запись) {
  const надо = НАСТРОЙКИ.хранение.версияЗаписи;

  /*  Портрет, нарисованный не тем источником, что стоит в настройках
      сейчас. Проверяется ОТДЕЛЬНО от версии записи: переезд на FLUX —
      это смена одной строки, а не новое устройство хранения.       */
  if (запись.портрет && запись.источникПортрета !== НАСТРОЙКИ.портрет.источник) {
    запись.портретСтарый = true;
    запись.попыток = 0;
  }

  if ((запись.версия || 1) >= надо) return запись;
  if (запись.портрет) {
    запись.портретСтарый = true;
    запись.попыток = 0;
  }

  /*  ДЕВИЗ БЫЛ НОМЕРОМ в списке. Переводим в ключ по тому же номеру:
      пока список не менялся, девиз у человека остаётся прежним.
      Дальше он живёт ключом и от перестановок не зависит.        */
  if (typeof запись.девиз === 'number') {
    const девизы = МИР.народы[запись.народ].девизы;
    const д = девизы[запись.девиз] || девизы[0];
    запись.девиз = д.ключ;
  }

  /*  Пола в старых записях не было — модель решала сама и рисовала
      всем мужчин. Достаём из зерна: оно у каждого героя своё, и полы
      разойдутся, а не лягут все на один. Так же сделано с плащом.  */
  if (!запись.пол) {
    запись.пол = МИР.полы[(запись.зерно || 0) % МИР.полы.length].ключ;
  }

  /*  Трёх цветов фигурки в старых записях не было — они появились
      вместе с картой. Достаём их из того, что человек уже выбрал:
      кожу из облика, волосы из народа. Плащ он не выбирал никогда,
      поэтому берём по зерну — у каждого героя своё, и цвета выйдут
      разные, а не один на всех.                                   */
  if (!запись.цветКожи) {
    if (!запись.плащ) {
      запись.плащ = МИР.плащи[(запись.зерно || 0) % МИР.плащи.length].имя;
    }
    запись.цветПлаща = цветПлаща(запись);
    запись.цветКожи  = цветКожи(запись);
    запись.цветВолос = МИР.народы[запись.народ].волосы;
  }

  запись.версия = надо;
  return запись;                 // сохраняет `достать`, после проверки
}

/*  Дописываем в запись адрес фигуры из библиотеки.

    Мир читает запись из памяти браузера НАПРЯМУЮ, мимо сборки, и про
    библиотеку с ключами выбора ничего не знает — запись единственное,
    что между ними. Поэтому адрес не считается на месте, а лежит в
    записи.

    Пересчитывается при каждой выдаче и переписывается, если разошёлся:
    имена папок живут в настройках, и запись, пролежавшая в браузере
    месяц, не должна тянуть за собой старый путь.                   */
function снабдитьЛицом(з) {
  з.фигураИзБиблиотеки = фигураИзБиблиотеки(з);
  return з;
}

function стереть() {
  try { localStorage.removeItem(НАСТРОЙКИ.хранение.ключ); } catch (е) {}
}

/* ═══ 10 · ГОТОВЫЙ ГЕРОЙ ═══════════════════════════════════════════ */

/*  Девиз по ключу. Не нашёлся — берём первый: народ мог лишиться
    девиза при правке мир.js, но герой из-за этого пропасть не должен. */
function девизГероя(з) {
  const девизы = МИР.народы[з.народ].девизы;
  return девизы.find((д) => д.ключ === з.девиз) || девизы[0];
}

function показатьГероя(з) {
  const н = МИР.народы[з.народ];
  применитьОттенок(з.народ);
  $('имя-героя').textContent = з.имя;
  $('род-героя').textContent = подставить(МИР.шаблоны.род,
    { народ: н.имя.toLowerCase(), земля: н.земля });
  $('судьба-героя').textContent = строкаСудьбы(з);
  $('девиз-героя').textContent = подставить(МИР.шаблоны.девиз,
    { девиз: девизГероя(з).текст });
  $('подпись-мира').textContent = МИР.подпись;
  показатьЭкран('э-герой');
  показатьПортрет(з);
}

function создатьГероя() {
  герой = {
    версия: НАСТРОЙКИ.хранение.версияЗаписи,
    имя: выбор.имя,
    народ: выбор.народ,
    пол: выбор.пол,
    телосложение: выбор.телосложение,
    цвет: выбор.цвет,
    отметина: выбор.отметина,
    плащ: выбор.плащ,

    /*  ТРИ ЦВЕТА ФИГУРКИ. Лежат в записи готовыми кодами, а не
        именами: фигурку рисует карта, и она не должна знать ничего
        про данные сборки. Запись — единственное, что между ними.  */
    цветПлаща: цветПлаща(выбор),
    цветКожи:  цветКожи(выбор),
    цветВолос: МИР.народы[выбор.народ].волосы,
    зерно: выбор.зерно,
    девиз: выбор.девиз,        // сохраняем, иначе девиз менялся бы при каждом входе
    попыток: 0,                // сколько раз портрет уже получен
    портрет: null,             // своя фигура, если человек её нарисовал

    /*  Чем нарисован портрет. При смене источника в настройках все
        записи с другим значением метятся старыми и пересоздаются
        молча — см. `перевести`.                                    */
    источникПортрета: null,
    создан: new Date().toISOString()
  };
  снабдитьЛицом(герой);
  сохранить(герой);
  показатьГероя(герой);          // карточка готова, хотя её сейчас не видно

  /*  ЛИЦО УЖЕ ЕСТЬ. Оно взято из библиотеки по ключам выбора — это
      готовый файл, а не заказ: ни ожидания, ни сети, ни отказа.

      Живая генерация осталась под кнопкой «нарисовать моё лицо» в
      карточке. Раньше здесь висели 45 секунд ожидания на каждого
      героя, и мир открывался без лица у тех, кому не повезло.     */
  if (приГотовности) приГотовности();
}

/*  Одно место, где пришедшее ложится в запись. Их три — создание,
    «ещё раз» и молчаливая замена старого, — и раньше каждое
    раскладывало поля само. Медальон бы в одном из них забыли.      */
function положитьПортрет(з, вышло) {
  if (!вышло.фигура) return false;
  з.портрет = вышло.фигура;        // своя фигура, а не библиотечная
  з.источникПортрета = вышло.источник;
  з.портретСтарый = false;
  return true;
}

/* ═══ 11 · КАРТОЧКА ДЛЯ ЧАТА ═══════════════════════════════════════
   Отдельная картинка, а не снимок экрана: её отправляют в чат, и там
   она живёт сама по себе. Смотреть на неё надо мелко, в ленте.      */

function перенос(кисть, текст, ширина) {
  const слова = текст.split(' ');
  const строки = [];
  let текущая = '';
  for (const слово of слова) {
    const проба = текущая ? текущая + ' ' + слово : слово;
    if (кисть.measureText(проба).width > ширина && текущая) {
      строки.push(текущая);
      текущая = слово;
    } else {
      текущая = проба;
    }
  }
  if (текущая) строки.push(текущая);
  return строки;
}

async function собратьКарточку(з) {
  const к = НАСТРОЙКИ.карточка;
  const холст = $('холст');
  холст.width = к.ширина;
  холст.height = к.высота;
  const кисть = холст.getContext('2d');
  const н = МИР.народы[з.народ];
  const поле = к.ширина * к.поле;
  const внутри = к.ширина - поле * 2;

  кисть.fillStyle = к.цвета.фон;
  кисть.fillRect(0, 0, к.ширина, к.высота);

  // портрет или знак народа на его месте
  const сторона = к.ширина * к.портретДоля;
  const портретX = (к.ширина - сторона) / 2;
  const портретY = поле;
  if (з.портрет) {
    const кадр = await new Promise((готово, мимо) => {
      const и = new Image();
      и.onload = () => готово(и);
      и.onerror = мимо;
      и.src = з.портрет;
    });
    кисть.drawImage(кадр, портретX, портретY, сторона, сторона);
  } else {
    кисть.fillStyle = к.цвета.рамка;
    кисть.fillRect(портретX, портретY, сторона, сторона);
  }
  кисть.strokeStyle = н.оттенок;
  кисть.lineWidth = Math.max(1, к.ширина * к.толщинаРамки);
  кисть.strokeRect(портретX, портретY, сторона, сторона);

  let y = портретY + сторона + к.ширина * к.отступПослеПортрета;
  кисть.textAlign = 'center';

  // знак народа: метка принадлежности, её требует ТЗ
  const знакСторона = к.ширина * к.знакДоля;
  const знак = await знакКартинкой(з.народ, знакСторона);
  if (знак) кисть.drawImage(знак, (к.ширина - знакСторона) / 2, y, знакСторона, знакСторона);
  y += знакСторона + к.ширина * к.отступПослеЗнака;

  кисть.fillStyle = к.цвета.текст;
  кисть.font = к.жирностьИмени + ' ' + (к.ширина * к.кегльИмени) + 'px ' + к.шрифт;
  кисть.fillText(з.имя, к.ширина / 2, y);

  y += к.ширина * к.отступПослеИмени;
  кисть.fillStyle = н.оттенок;
  кисть.font = (к.ширина * к.кегльНарода) + 'px ' + к.шрифт;
  кисть.fillText(подставить(МИР.шаблоны.род,
    { народ: н.имя.toLowerCase(), земля: н.земля }), к.ширина / 2, y);

  y += к.ширина * к.отступПослеНарода;
  кисть.fillStyle = к.цвета.тусклый;
  кисть.font = (к.ширина * к.кегльСудьбы) + 'px ' + к.шрифт;
  for (const строка of перенос(кисть, строкаСудьбы(з), внутри)) {
    кисть.fillText(строка, к.ширина / 2, y);
    y += к.ширина * к.кегльСудьбы * к.межстрочный;
  }

  кисть.font = (к.ширина * к.кегльПодписи) + 'px ' + к.шрифт;
  кисть.fillStyle = к.цвета.тусклый;
  кисть.fillText(подставить(МИР.шаблоны.низКарточки,
    { подпись: МИР.подпись, призыв: МИР.тексты.карточка_призыв }),
    к.ширина / 2, к.высота - поле);

  return await new Promise((готово) => холст.toBlob(готово, 'image/png'));
}

function скачать(двоичное, имяФайла) {
  const адрес = URL.createObjectURL(двоичное);
  const ссылка = document.createElement('a');
  ссылка.href = адрес;
  ссылка.download = имяФайла;
  document.body.appendChild(ссылка);
  ссылка.click();
  ссылка.remove();
  setTimeout(() => URL.revokeObjectURL(адрес), НАСТРОЙКИ.портрет.ожиданиеМс);
}

async function показатьДрузьям() {
  $('к-показать').disabled = true;
  try {
    const двоичное = await собратьКарточку(герой);
    const файл = new File([двоичное], НАСТРОЙКИ.карточка.имяФайла, { type: 'image/png' });
    if (navigator.canShare && navigator.canShare({ files: [файл] })) {
      await navigator.share({ files: [файл] });
      $('сообщение').textContent = '';
    } else {
      скачать(двоичное, НАСТРОЙКИ.карточка.имяФайла);
      $('сообщение').textContent = МИР.тексты.поделиться_ошибка;
    }
  } catch (е) {
    $('сообщение').textContent = МИР.тексты.поделиться_ошибка;
  } finally {
    $('к-показать').disabled = false;
  }
}

/* ═══ 12 · СОБЫТИЯ ═════════════════════════════════════════════════ */

function повеситьСобытия() {
  $('к-начать').addEventListener('click', () => {
    показатьЭкран('э-конструктор');
    перерисоватьВсё();
    показатьШаг(1);
  });

  document.querySelectorAll('[data-вперёд]').forEach((кн) =>
    кн.addEventListener('click', () => показатьШаг(Number(кн.dataset.вперёд))));
  document.querySelectorAll('[data-назад]').forEach((кн) =>
    кн.addEventListener('click', () => показатьШаг(Number(кн.dataset.назад))));
  document.querySelectorAll('[data-перемешать]').forEach((кн) =>
    кн.addEventListener('click', перемешать));

  // выбор внутри списков ловим на всплытии: списки перерисовываются
  $('народы').addEventListener('click', (с) => {
    const узел = с.target.closest('[data-народ]');
    if (узел) выбратьНарод(узел.dataset.народ);
  });
  $('шаг-2').addEventListener('click', (с) => {
    const у = с.target.closest(
      '[data-пол],[data-телосложение],[data-цвет],[data-отметина]');
    if (!у) return;
    if (у.dataset.пол) выбор.пол = у.dataset.пол;
    if (у.dataset.телосложение) выбор.телосложение = у.dataset.телосложение;
    if (у.dataset.цвет) выбор.цвет = у.dataset.цвет;
    if (у.dataset.отметина) выбор.отметина = у.dataset.отметина;
    нарисоватьОблик();
    обновитьПревью();
  });

  $('поле-имя').addEventListener('input', проверитьИмя);
  $('к-подтвердить').addEventListener('click', создатьГероя);
  $('к-показать').addEventListener('click', показатьДрузьям);
  $('к-портрет').addEventListener('click', догнатьПортрет);
  /*  Поломка — наша ошибка, и первое, что предлагаем, это повторить:
      обычно к этому мигу выложена уже исправленная версия. Стирание
      прежнего героя стоит второй кнопкой и спрашивает.             */
  $('к-починить').addEventListener('click', () => location.reload());
  $('к-сначала').addEventListener('click', () => {
    if (!confirm(МИР.тексты.поломка_вопрос)) return;
    стереть();
    поломка = false;
    $('поломка').hidden = true;
    $('к-начать').hidden = false;
  });

  $('к-заново').addEventListener('click', () => {
    if (!confirm(МИР.тексты.заново_вопрос)) return;
    стереть();
    герой = null;
    выбор = случайныйВыбор();
    $('поле-имя').value = '';
    $('сообщение').textContent = '';
    показатьЭкран('э-вступление');
  });
}

/* ═══ 13 · ЗАПУСК ══════════════════════════════════════════════════ */

function запуск() {
  расставитьТексты();

  $('полоска').innerHTML = '<i></i>'.repeat(НАСТРОЙКИ.шагов);
  $('поле-имя').maxLength = НАСТРОЙКИ.имя.макс;
  $('поле-имя').placeholder = МИР.тексты.поле_имя;

  выбор = случайныйВыбор();
  повеситьСобытия();

  const прочитано = достать();
  герой = прочитано.запись || null;
  поломка = Boolean(прочитано.поломка);

  if (поломка) показатьПоломку();
  else if (герой) обновитьСтарыйПортрет();  // без ожидания: экран покажут отдельно
}

/* ═══ 14 · ЧТО ВИДНО СНАРУЖИ ═══════════════════════════════════════
   Переключением экранов заведует вэрн.be4d00a6.js — он один знает про все три
   части адреса. Отсюда наружу уходит только необходимое.          */

let приГотовности = null;

return {
  запуск: запуск,

  /* Показать сборку с начала — из ворот или кнопкой «переделать». */
  показать: function () {
    if (герой) показатьГероя(герой);
    else показатьЭкран('э-вступление');
  },

  есть:  () => Boolean(герой),

  /*  Запись есть, но не читается. Отдельно от «есть»: переключателю
      надо развести ворота и разговор о поломке.                    */
  поломка: () => поломка,
  запись: () => герой,

  /* Кого позвать, когда герой готов и пора в мир. */
  когдаГотов: function (что) { приГотовности = что; },
  вМир: function () { if (приГотовности) приГотовности(); }
};
})();
